insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,sumber_pdf,halaman,kalimat,kalimat_ruby,kosakata) values
('宿泊分野（1号）','フロントの仕事は何と呼ばれますか？','["宿泊施設の顔", "裏方", "管理部門", "営業所"]'::jsonb,0,'フロントは「宿泊施設の顔」と呼ばれます。',501,'1号 · 01 · フロント業務','1号',5,'お客様が宿泊施設に到着してから宿 泊施設を出発するまでの間、お客様の対応をする「宿泊施設の顔」 とも言える仕事で、お客様が宿泊施設での時間を快適に過ごす ためには欠かすことのできない大切な業務を行います。',null,'[]'::jsonb),
('宿泊分野（1号）','部屋が空いていない状態を何といいますか？','["満室", "空室", "空き待ち", "キャンセル待ち"]'::jsonb,0,'空いていない状態＝満室、空いている状態＝空室です。',502,'1号 · 01 · フロント業務','1号',7,'お部屋が空いていな い状態のことを「満室」、お部屋が 空いている状態を「空室」と言いま す。 空室 あ き し つ 満室 ま ん し つ フロントで行う主な業務 予約管理 1. チェックイン業務 2. 館内でのお客様対応と 情報提供 3. チェックアウト･会計業務 4. A. 予約問い合わせへの',null,'[]'::jsonb),
('宿泊分野（1号）','部屋が空いている状態を何といいますか？','["空室", "満室", "予約済", "点検中"]'::jsonb,0,'空いている状態＝空室です。',503,'1号 · 01 · フロント業務','1号',7,'お部屋が空いていな い状態のことを「満室」、お部屋が 空いている状態を「空室」と言いま す。 空室 あ き し つ 満室 ま ん し つ フロントで行う主な業務 予約管理 1. チェックイン業務 2. 館内でのお客様対応と 情報提供 3. チェックアウト･会計業務 4. A. 予約問い合わせへの対応 B. お客様情報の確認 C.',null,'[]'::jsonb),
('宿泊分野（1号）','宿泊予定日・氏名などを事前に確認する目的はどれですか？','["ノーショーを防ぐ", "料金を上げる", "清掃を減らす", "部屋を減らす"]'::jsonb,0,'事前確認でノーショーを防ぎます。',504,'1号 · 01 · フロント業務','1号',8,'上記を事前にお聞きし、お客様に宿泊予定日に必ず来ていただくこと（ノーショーの防止） をお約束するとともに、宿泊施設として最高のおもてなしをお客様に提供する準備ができ るようにします。',null,'[]'::jsonb),
('宿泊分野（1号）','宿泊料金に含まれない館内サービスを何といいますか？','["館内利用", "素泊まり", "オールインクルーシブ", "デポジット"]'::jsonb,0,'飲料・ルームサービス・マッサージなどは館内利用です。',505,'1号 · 01 · フロント業務','1号',17,'お客様がご宿泊以外の館内でご利用したサービス（プランには含まれていない飲料、ルー ムサービス、マッサージなど）を「館内利用」といいます。館内利用の有無とその内容を お客様のチェックアウトの際に確認します。',null,'[]'::jsonb),
('宿泊分野（1号）','1泊2食プランは主にどこで販売されていますか？','["旅館", "ホテル", "空港", "旅行代理店のみ"]'::jsonb,0,'1泊2食は主に旅館で販売されています。',506,'1号 · 02 · 企画・広報','1号',21,'・１泊２食 宿泊料金の中に夕食と朝食が含まれている宿泊プランです。主に旅館で販売されています ・ベッド& ブレックファースト（B＆B） 宿泊料金の中に朝食のみ含まれている宿泊プランです。',null,'[]'::jsonb),
('宿泊分野（1号）','B&B（朝食のみ）プランは主にどこで販売されていますか？','["ホテル", "旅館", "民宿のみ", "駅"]'::jsonb,0,'B&Bは主にホテルで販売されています。',507,'1号 · 02 · 企画・広報','1号',21,'主に旅館で販売されています ・ベッド& ブレックファースト（B＆B） 宿泊料金の中に朝食のみ含まれている宿泊プランです。主にホテルで販売されています ・連泊 同じ宿泊施設で2 泊以上の連続した宿泊を指します。',null,'[]'::jsonb),
('宿泊分野（1号）','同じ施設に2泊以上続けて泊まることを何といいますか？','["連泊", "ウォークイン", "デイユース", "素泊まり"]'::jsonb,0,'2泊以上＝連泊で、割引や特典がある場合があります。',508,'1号 · 02 · 企画・広報','1号',21,'主にホテルで販売されています ・連泊 同じ宿泊施設で2 泊以上の連続した宿泊を指します。連泊は割引料金や特典を得ることが できる場合があります ・ウォークイン 事前の予約なしに直接宿泊施設に訪れてサービスを利用することを指します。',null,'[]'::jsonb),
('宿泊分野（1号）','預り金は別名何と表記されますか？','["デポジット", "チップ", "サービス料", "宿泊税"]'::jsonb,0,'預り金はデポジットと表記されることもあります。',509,'1号 · 02 · 企画・広報','1号',21,'ますが、予期せず立ち寄った顧客が空いてい る客室を利用することも可能です ・預り金 サービスの利用を保証するために支払われる金額を指します。デポジットと表記されるこ ともあります ・ダイレクトブッキング 旅行会社、OTA などの代行会社を利用せずに直接交渉や予約、契約まで行うことです。',null,'[]'::jsonb),
('宿泊分野（1号）','OTAとは何の略ですか？','["Online Travel Agent", "Open Travel Area", "Online Ticket Agency", "Over Time Allowance"]'::jsonb,0,'OTA＝オンライン旅行代理店です。',510,'1号 · 02 · 企画・広報','1号',21,'施設側のメリットとしては手数料負担を減らすことができます ・OTA Online Travel Agent の略語です。インターネットを介して旅行商品やサービスを提供す るオンライン旅行代理店のことです ・FIT Free Independent Traveler の略語であり、自由な個人旅行者を指します。',null,'[]'::jsonb),
('宿泊分野（1号）','FITとはどのような旅行者ですか？','["自由な個人旅行者", "団体客", "法人客", "添乗員"]'::jsonb,0,'FIT＝Free Independent Traveler（個人旅行者）。',511,'1号 · 02 · 企画・広報','1号',21,'て旅行商品やサービスを提供す るオンライン旅行代理店のことです ・FIT Free Independent Traveler の略語であり、自由な個人旅行者を指します。主に旅行代理 店やツアーオペレーターが提供するツアーパッケージを利用せず、自分旅行のプランを作 り、現地で自由に行動する旅行スタイルを指します。',null,'[]'::jsonb),
('宿泊分野（1号）','過去に利用し、その後も繰り返し来るお客様を何といいますか？','["リピーター", "ウォークイン", "FIT", "OTA"]'::jsonb,0,'繰り返し利用するお客様＝リピーターです。',512,'1号 · 02 · 企画・広報','1号',22,'・リピーター 施設を過去に利用したことがあり、その後も何度か繰り返しご利用いただいているお客様 のことを指します ・稼働率 宿泊施設の部屋の稼働状況を計る数字で、Occupancy Rate、OCC と表記されることもあ ります。',null,'[]'::jsonb),
('宿泊分野（1号）','稼働率の英語表記はどれですか？','["Occupancy Rate（OCC）", "Average Daily Rate（ADR）", "Revenue Per Available Room（RevPAR）", "Free Independent Traveler（FIT）"]'::jsonb,0,'稼働率＝Occupancy Rate（OCC）です。',513,'1号 · 02 · 企画・広報','1号',22,'去に利用したことがあり、その後も何度か繰り返しご利用いただいているお客様 のことを指します ・稼働率 宿泊施設の部屋の稼働状況を計る数字で、Occupancy Rate、OCC と表記されることもあ ります。',null,'[]'::jsonb),
('宿泊分野（1号）','ADRの計算方法はどれですか？','["宿泊売上合計÷稼働客室数", "予約室数÷総室数×100", "OCC×ADR", "売上−人件費"]'::jsonb,0,'ADR＝宿泊売上合計÷稼働客室数です。',514,'1号 · 02 · 企画・広報','1号',22,'計算方法は、 宿泊による売り上げ合計額÷ 稼働している客室数で算出します。ADR は、ホテルの収益 管理戦略や業績評価において重要な指標として使用されます。高いADR は、ホテルの部 屋を高く売ることができることを示し、収益の増加につながります。',null,'[]'::jsonb),
('宿泊分野（1号）','RevPARの計算方法はどれですか？','["OCC × ADR", "予約数 ÷ 総室数", "売上 ÷ 従業員数", "客室数 × 料金"]'::jsonb,0,'RevPAR＝OCC×ADRです。',515,'1号 · 02 · 企画・広報','1号',22,'ことを示し、収益性の低下につな がる可能性があります ・RevPAR の説明 販売可能な客室一室あたりの収益を表す値のことです。計算方法は、客室稼働率（OCC） × 客室平均単価（ADR）で算出します。',null,'[]'::jsonb),
('宿泊分野（1号）','客室価格を調整して収益を最大化する経営手法はどれですか？','["レベニューマネジメント", "F&Bコントロール", "ABC分析", "セグメンテーション"]'::jsonb,0,'レベニューマネジメントで収益を最大化します。',516,'1号 · 02 · 企画・広報','1号',22,'施設の 経営状況を把握するにはRevPAR も常にチェックし、客室稼働率・客室平均単価を調整 して収益を最大化させる適切な判断が必要です ・レベニューマネジメント 戦略的に施設の客室を販売し、より効率的に利益を確保するべく、客室の価格をコントロー ルすることです。',null,'[]'::jsonb),
('宿泊分野（1号）','広報業務とはどのような仕事ですか？','["自社の活動や商品の情報を発信する", "会計をする", "清掃する", "予約を取る"]'::jsonb,0,'広報業務は情報発信の仕事です。',517,'1号 · 02 · 企画・広報','1号',23,'情報発信をすることで、自社のことを、ステークホルダー（旅行者、関係取引先、株主、 自社の従業員、地域住民など）に良く知ってもらい、良い関係を作ることができます。また、 自社の企業としての価値をあげることや、自社のことをより多くの',null,'[]'::jsonb),
('宿泊分野（1号）','お客様が自分の体験を発信することを何といいますか？','["口コミ", "プレスリリース", "ブランディング", "セグメンテーション"]'::jsonb,0,'お客様の体験発信＝口コミで、集客に大きな力になります。',518,'1号 · 02 · 企画・広報','1号',23,'また、お客様がチェックアウトした後、お客様ご自 身の体験を自分で発信する「口コミ」も集客する時に大きな力となります。 企画・広報について 1.企画業務 2. 広報業務 A. 自社ホームページの運用方法 B . SNSの運用方法 企画・広報について 1.企画業務 2.広報業務 こうほうぎょうむ かつどうないよう しゅくはくしせつ しょ',null,'[]'::jsonb),
('宿泊分野（1号）','SEOとは何ですか？','["検索エンジン最適化", "顧客満足度調査", "価格戦略", "予約管理"]'::jsonb,0,'SEO＝検索エンジン最適化です。',519,'1号 · 02 · 企画・広報','1号',24,'また、旅行会社、OTA などの 会社を利用せずに予約、契約まで行うことでき、手数料を減らすことができます。 ・検索エンジン最適化 (SEO) 検索エンジンでのウェブサイトの表示順位を向上させるために、適切なキーワードの使用、 コンテンツの質の向上など、SEO に取り組みます。',null,'[]'::jsonb),
('宿泊分野（1号）','満足度を把握するために行うことはどれですか？','["顧客のフィードバックを集める", "料金を上げる", "口コミを消す", "写真を減らす"]'::jsonb,0,'フィードバックを集めて改善点を把握します。',520,'1号 · 02 · 企画・広報','1号',24,'検索エンジンでのウェブサイトの表示順位を向上させるために、適切なキーワードの使用、 コンテンツの質の向上など、SEO に取り組みます。 ・顧客のフィードバックの収集 客室やサービスの満足度を把握するために、顧客からのフィードバックをよく集め、 改善点をしっかりと理解します。',null,'[]'::jsonb),
('宿泊分野（1号）','SNS運用で最初に計画すべきことはどれですか？','["コンテンツ戦略の策定", "フォロワー購入", "毎日同じ投稿", "コメント削除"]'::jsonb,0,'SNSはコンテンツ戦略の策定から始めます。',521,'1号 · 02 · 企画・広報','1号',25,'の運用方法 宿泊施設のSNS を上手に活用することで、お客様とのコミュニケーションを強化し、 施設のブランドを育成することができます。 ・コンテンツ戦略の策定 SNS 上でシェアするコンテンツを適切に計画することが重要です。',null,'[]'::jsonb),
('宿泊分野（1号）','SNSで効果的な取り組みはどれですか？','["お客様の投稿やレビューを活用する", "個人情報を載せる", "投稿を消す", "返信しない"]'::jsonb,0,'UGC（お客様生成コンテンツ）の活用が効果的です。',522,'1号 · 02 · 企画・広報','1号',25,'んで、お互いにSNS アカウントをタグ付けしたり、 共同キャンペーンを行ったりすることで、地域全体の観光を盛り上げていくことが重要です。 ・お客様生成コンテンツの活用 お客様が投稿した写真やレビューを積極的に活用することが重要です。',null,'[]'::jsonb),
('宿泊分野（1号）','SNS運用で定期的に行うべきことはどれですか？','["分析ツールで効果を測り改善する", "投稿をやめる", "フォロワーを買う", "同じ内容を繰り返す"]'::jsonb,0,'分析して戦略を改善します。',523,'1号 · 02 · 企画・広報','1号',25,'ハッシュタグや特定のキャンペーンを通じて、お客様からのコンテンツ提供を活発にします。 ・分析と改善 SNS の分析ツールを利用して、SNS での投稿の効果やフォロワーの動向を定期的に 分析することが重要です。',null,'[]'::jsonb),
('宿泊分野（1号）','あいさつするときの正しい態度はどれですか？','["明るく元気に笑顔で相手の目を見る", "下を向いて小声で", "早口で", "無表情で"]'::jsonb,0,'明るく笑顔で、相手の目を見て気持ちを込めます。',524,'1号 · 03 · 接客','1号',28,'あい さつする時は、明るく元気に笑顔で、 相手に届く声で、 相手の目を見て 、気持ちを込 めて、あいさつするようにします。 接客するうえで覚えておかなければいけないあいさつをいくつかご紹介します。',null,'[]'::jsonb),
('宿泊分野（1号）','お客様に何かお願いするときに使う言葉はどれですか？','["恐れ入りますが…", "お疲れさまでした", "お先に失礼します", "休憩に入ります"]'::jsonb,0,'「恐れ入りますが…」は依頼のときの表現です。',525,'1号 · 03 · 接客','1号',28,'る時に使います （※なお、こうした場合にはお客様にまずお詫びをしたうえで、すぐにチームの責任者に その内容を報告することが大切です。） ・「恐れ入りますが、・・・・・」 お客様にこちらから何かお願いする時に使います。',null,'[]'::jsonb),
('宿泊分野（1号）','退勤するときのあいさつはどれですか？','["お先に失礼します", "お疲れさまでした", "いらっしゃいませ", "かしこまりました"]'::jsonb,0,'退勤時は「お先に失礼します」です。',526,'1号 · 03 · 接客','1号',29,'・出勤時には、「おはようございます」と言います。 ・退勤時は、「お先に失礼します」と言います。 ・退勤する人へは、「お疲れさまでした」と言います。 ・休憩に入る時は、「休憩に入ります」と言います。',null,'[]'::jsonb),
('宿泊分野（1号）','退勤する人にかける言葉はどれですか？','["お疲れさまでした", "お先に失礼します", "恐れ入りますが", "少々お待ちください"]'::jsonb,0,'退勤する人には「お疲れさまでした」です。',527,'1号 · 03 · 接客','1号',29,'・退勤する人へは、「お疲れさまでした」と言います。 ・休憩に入る時は、「休憩に入ります」と言います。 また、従業員同士で名前を呼ぶ時は、名字に「さん」をつけて「〇〇さん」と呼びます。',null,'[]'::jsonb),
('宿泊分野（1号）','休憩に入るときのあいさつはどれですか？','["休憩に入ります", "お疲れさまでした", "お先に失礼します", "失礼いたします"]'::jsonb,0,'休憩時は「休憩に入ります」です。',528,'1号 · 03 · 接客','1号',29,'・休憩に入る時は、「休憩に入ります」と言います。 また、従業員同士で名前を呼ぶ時は、名字に「さん」をつけて「〇〇さん」と呼びます。 接客について 1.あいさつ 2.接客の基本姿勢とおじぎ 3.接客の際の話し方 4.具体的な接客方法 5.電話対応 6.クレーム（苦情）対応 つぎ し',null,'[]'::jsonb),
('宿泊分野（1号）','従業員同士で名前を呼ぶときの正しい方法はどれですか？','["名字に「さん」をつける", "下の名前を呼び捨て", "あだ名で呼ぶ", "名字だけ呼ぶ"]'::jsonb,0,'従業員同士は名字＋「さん」で呼びます。',529,'1号 · 03 · 接客','1号',29,'また、従業員同士で名前を呼ぶ時は、名字に「さん」をつけて「〇〇さん」と呼びます。 接客について 1.あいさつ 2.接客の基本姿勢とおじぎ 3.接客の際の話し方 4.具体的な接客方法 5.電話対応 6.クレーム（苦情）対応 つぎ しゅくはくしせつ おぼ じゅうぎょういんどうし はたら しょうかい',null,'[]'::jsonb),
('宿泊分野（1号）','接客で特に重要とされるものはどれですか？','["基本姿勢とおじぎ", "会計技術", "調理技術", "PC操作"]'::jsonb,0,'接客では基本姿勢とおじぎが重要です。',530,'1号 · 03 · 接客','1号',27,'次ページからフローチャートにそって、詳細を説明していきます 1.あいさつ 2.接客の基本姿勢とおじぎ 3.接客の際の話し方 4.具体的な接客方法 5.電話対応 6.クレーム（苦情）対応 接 客 接客について 1.あいさつ 2.接客の基本姿勢とおじぎ 3.接客の際の話し方 4.具体的な接客方法 5.電話対応 6.クレーム（苦情）対応 03 せ',null,'[]'::jsonb),
('宿泊分野（1号）','お客様が館内で探し物をしている様子のとき、かける言葉はどれですか？','["何かお探しでしょうか", "どこですか", "何をしていますか", "お待ちください"]'::jsonb,0,'「何かお探しでしょうか」と声をかけます。',531,'1号 · 03 · 接客','1号',33,'①お客様が館内で何か探されている様子の場合は、「何かお探しでしょうか」とお声がけ します。 ②宿泊施設内でお客様をご案内する際には、2 ～3 歩、左前方を、お客様の歩調に合わせ ながら歩きます。',null,'[]'::jsonb),
('宿泊分野（1号）','やむを得ず館内エレベーターを使うときの対応はどれですか？','["常にお客様を優先する", "先に乗る", "同僚と乗る", "使わない"]'::jsonb,0,'エレベーターは常にお客様を優先します。',532,'1号 · 03 · 接客','1号',33,'⑧やむを得ず館内エレベーターを使用する際には、常にお客様を優先します。 ⑨車いすのお客様とのコミュニケーションをとる時には、お客様と目の高さを合わせて対 応します。 ⑩視覚障がいのあるお客様が来館された時には、何かお手伝いが出来ることがないか、お 声かけをします。',null,'[]'::jsonb),
('宿泊分野（1号）','視覚に障害のあるお客様が来館したときの対応はどれですか？','["正面から声をかけ手伝いを申し出る", "黙って見守る", "背中から押す", "何もしない"]'::jsonb,0,'正面から声をかけ、手伝いを申し出ます。',533,'1号 · 03 · 接客','1号',33,'⑨車いすのお客様とのコミュニケーションをとる時には、お客様と目の高さを合わせて対 応します。 ⑩視覚障がいのあるお客様が来館された時には、何かお手伝いが出来ることがないか、お 声かけをします。',null,'[]'::jsonb),
('宿泊分野（1号）','杖を使うお客様をレストランに案内するときの対応はどれですか？','["希望があれば出入口に近い席へ", "奥の席へ", "立席へ", "案内しない"]'::jsonb,0,'希望があれば出入口に近い席に案内します。',534,'1号 · 03 · 接客','1号',33,'⑩視覚障がいのあるお客様が来館された時には、何かお手伝いが出来ることがないか、お 声かけをします。 ⑪杖をついた足の不自由な方がレストランにいらした時には、ご希望があれば出入り口に 近い席にご案内します。',null,'[]'::jsonb),
('宿泊分野（1号）','宿泊施設で最も重要なことはどれですか？','["お客様に満足していただくこと", "売上だけを伸ばす", "清掃を減らす", "客室を減らす"]'::jsonb,0,'「泊まって良かった」と満足してもらうことが最重要です。',535,'1号 · 03 · 接客','1号',33,'宿泊施設ではご宿泊のお客様に「泊まって良かったな」と満足していただくことが最も重 要であり、そのためにも従業員はどんな時でも丁寧な接客を行うことが必要です。お客様 に対しての心のこもった接客やサービス（日本では「おもてなし」と言います）を提供し なければいけません。',null,'[]'::jsonb),
('宿泊分野（1号）','電話を取る前に準備するものはどれですか？','["メモと筆記用具", "名刺", "電卓", "鍵"]'::jsonb,0,'電話を取る前にメモと筆記用具を用意します。',536,'1号 · 03 · 接客','1号',34,'電話対応のポイントは、 ・電話を取る前にメモと筆記用具を用意しておく ・電話に出たら、まず名乗る ・電話を取り次ぐ場合は、相手の名前（会社名）を確認する ・特にお客様からの電話は、相手が受話器を置いたのを確認してから、受話器を置く ことです。',null,'[]'::jsonb),
('宿泊分野（1号）','電話に出たとき最初にすることはどれですか？','["まず名乗る", "相手の名前を聞く", "切る", "保留にする"]'::jsonb,0,'電話に出たらまず名乗ります。',537,'1号 · 03 · 接客','1号',34,'電話対応のポイントは、 ・電話を取る前にメモと筆記用具を用意しておく ・電話に出たら、まず名乗る ・電話を取り次ぐ場合は、相手の名前（会社名）を確認する ・特にお客様からの電話は、相手が受話器を置いたのを確認してから、受話器を置く ことです。',null,'[]'::jsonb),
('宿泊分野（1号）','電話を取り次ぐときに確認することはどれですか？','["相手の名前（会社名）", "天気", "予定", "料金"]'::jsonb,0,'取り次ぐ前に相手の名前・会社名を確認します。',538,'1号 · 03 · 接客','1号',34,'電話対応のポイントは、 ・電話を取る前にメモと筆記用具を用意しておく ・電話に出たら、まず名乗る ・電話を取り次ぐ場合は、相手の名前（会社名）を確認する ・特にお客様からの電話は、相手が受話器を置いたのを確認してから、受話器を置く ことです。',null,'[]'::jsonb),
('宿泊分野（1号）','「おもてなし」は英語で何と同じ意味ですか？','["ホスピタリティ", "サービスチャージ", "マナー", "エチケット"]'::jsonb,0,'おもてなし＝ホスピタリティです。',539,'1号 · 04 · レストランサービス','1号',36,'なお、「おもてなし」は英語のホスピタリティ(Hospitality) と同意語となり ます。 ホテル・旅館での食事は、滞在されるお客様にとっての楽しみの一つであり、 お客様に「おもてなし」を伝えるためには、基本動作・決められたルール やマナーを身に着けることが大切です。',null,'[]'::jsonb),
('宿泊分野（1号）','レストラン接客でお客様の印象を良くするにはどれですか？','["笑顔を意識する", "無表情で接する", "早口で話す", "目を合わせない"]'::jsonb,0,'笑顔を意識すると印象が良くなります。',540,'1号 · 04 · レストランサービス','1号',37,'また、レストランで接客する際には、表情もとても大切な要素です。笑顔を意識することで、 お客様の印象も良くなります。大切なポイントは以下のとおりです。 1.サービスの基本動作 ・相手の目を見て、元気ではっきりとした声であいさつをすること ・お客様を見かけたら、自分から積極的にあいさつをすること ・笑顔をつくるときは、「口の',null,'[]'::jsonb),
('宿泊分野（1号）','チェックイン時に説明する内容として正しいのはどれですか？','["客室への行き方や利用時間", "従業員の休憩時間", "仕入れ先", "建物の所有者"]'::jsonb,0,'客室への行き方・利用時間・非常口などを説明します。',541,'1号 · 01 · フロント業務','1号',12,'その際に気を付けなければいけないことは、お 客様が館内で迷わないように、お部屋への行き方、館内の利用できる場所への行き方や利 用可能な時間、さらには、火災や自然災害時に利用する非常口と避難経路などを丁寧に説 明する必要があります。',null,'[]'::jsonb),
('宿泊分野（1号）','敬語の使い方として正しいのはどれですか？','["3種類を場面で使い分ける", "1種類だけ使う", "使わない", "お客様には使わない"]'::jsonb,0,'敬語は3種類を適切に使い分けます。',542,'1号 · 03 · 接客','1号',32,'敬語には3 種類あり、それらを使い分ける必要があります。 3.接客の際の話し方 接客について 1.あいさつ 2.接客の基本姿勢とおじぎ 3.接客の際の話し方 4.具体的な接客方法 5.電話対応 6.クレーム（苦情）対応 せっきゃく さい きゃくさま め み はな あんない たいせつ えがお',null,'[]'::jsonb),
('宿泊分野（1号）','あいさつで大切なことはどれですか？','["気持ちを込めて伝える", "小声で言う", "早口で言う", "目を閉じる"]'::jsonb,0,'明るく笑顔で、気持ちを込めてあいさつします。',543,'1号 · 03 · 接客','1号',28,'あい さつする時は、明るく元気に笑顔で、 相手に届く声で、 相手の目を見て 、気持ちを込 めて、あいさつするようにします。 接客するうえで覚えておかなければいけないあいさつをいくつかご紹介します。',null,'[]'::jsonb),
('宿泊分野（1号）','料理を運ぶときに注意すべきことはどれですか？','["お皿の持ち方", "歩幅", "声量", "靴ひも"]'::jsonb,0,'お皿の持ち方に注意が必要です。',544,'1号 · 04 · レストランサービス','1号',39,'親指が料理に ついたり、お皿に指紋がつかないように気を付けます。また、お料理の正しい向きを確認 して、必ずお客様から見て、お料理が正面にくるように提供します。洋食では、基本的に はお料理は左側から提供します。',null,'[]'::jsonb),
('宿泊分野（1号）','チェックイン業務の正しい流れはどれですか？','["予約確認→宿泊手続き→鍵の受け渡し→館内説明", "鍵→予約確認→会計→清掃", "会計→予約確認→鍵", "清掃→鍵→会計"]'::jsonb,0,'予約を確認し、手続き・鍵の受け渡し・館内説明の順に進めます。',545,'1号 · 01 · フロント業務','1号',10,'2.チェックイン業務 チェックイン業務は、お客様が宿泊施設に到着した際に、フロントでお客様の受付をする 業務のことで、予約内容を確認し、ご宿泊の手続き、ルームキーのお渡し、館内・設備の 説明などをして、お客様に安心してご宿泊していただけるようにご案内をする業務です。',null,'[]'::jsonb);
